import { toUploadCategory } from "./categories.js";
import { unwrapStepsAttachments } from "./resolvers.js";
export const categoryDisplayName = (cat) => cat.name ?? cat.grouping?.[0]?.name ?? cat.grouping?.[0]?.value ?? cat.grouping?.[0]?.key ?? cat.externalId;
export const enrichWithCategories = async (store, trs, contextCategories) => {
    return Promise.all(trs.map(async (tr) => {
        const environmentId = await store.environmentIdByTrId(tr.id);
        const base = {
            ...tr,
            ...(environmentId ? { environment: environmentId } : {}),
            steps: unwrapStepsAttachments(tr.steps),
        };
        const category = toUploadCategory(base, contextCategories ?? []);
        if (category) {
            base.category = category;
        }
        return base;
    }));
};
const collectCategoryNamesByExternalId = (trs) => {
    const map = new Map();
    for (const tr of trs) {
        const cat = tr.category;
        if (cat?.externalId) {
            map.set(cat.externalId, categoryDisplayName(cat));
        }
    }
    return map;
};
const assignCreatedCategoryIds = (trs, idByExternalId) => {
    for (const tr of trs) {
        const cat = tr.category;
        if (!cat?.externalId) {
            continue;
        }
        const id = idByExternalId.get(cat.externalId);
        if (typeof id === "number") {
            tr.category = { ...cat, id };
        }
    }
};
export const syncLaunchCategories = async (client, trs, contextCategories) => {
    const categoryNamesByExternalId = collectCategoryNamesByExternalId(trs);
    if (categoryNamesByExternalId.size === 0) {
        return undefined;
    }
    const bulkItems = [];
    const seenExternalIds = new Set();
    for (const tr of trs) {
        const cat = tr.category;
        if (!cat?.externalId)
            continue;
        if (seenExternalIds.has(cat.externalId))
            continue;
        seenExternalIds.add(cat.externalId);
        bulkItems.push({
            externalId: cat.externalId,
            name: categoryNamesByExternalId.get(cat.externalId) ?? categoryDisplayName(cat),
            hide: cat.hide,
            expand: cat.expand,
        });
    }
    const rankByExternalId = new Map();
    for (const category of contextCategories) {
        if (!rankByExternalId.has(category.id)) {
            rankByExternalId.set(category.id, category.index);
        }
        if (!rankByExternalId.has(category.name)) {
            rankByExternalId.set(category.name, category.index);
        }
    }
    const ranked = bulkItems.map((item, originalIndex) => ({
        item,
        originalIndex,
        rank: rankByExternalId.get(item.externalId),
    }));
    ranked.sort((first, second) => {
        const firstRank = first.rank ?? Number.POSITIVE_INFINITY;
        const secondRank = second.rank ?? Number.POSITIVE_INFINITY;
        if (firstRank !== secondRank)
            return firstRank - secondRank;
        return first.originalIndex - second.originalIndex;
    });
    const orderedBulkItems = ranked.map((rankedItem) => rankedItem.item);
    const launchId = client.launchId;
    if (launchId === undefined) {
        return new Error("Launch isn't created, skipping launch categories");
    }
    try {
        const created = await client.createLaunchCategoriesBulk(launchId, orderedBulkItems);
        const categoryIdByExternalId = new Map(created.map((result) => [result.externalId, result.id]));
        assignCreatedCategoryIds(trs, categoryIdByExternalId);
        return undefined;
    }
    catch (error) {
        return error instanceof Error ? error : new Error(String(error));
    }
};
